import { gql } from '@apollo/client';

export interface Car {
  id: string;
  make: string;
  model: string;
  year: number;
  color?: string;
  price: number;
  mileage?: number;
  status?: string;
  description?: string;
  createdAt?: string;
  updatedAt?: string;
}

export interface AddCarInput {
  make: string;
  model: string;
  year: number;
  color?: string;
  price: number;
  mileage?: number;
  status?: string;
  description?: string;
}

export interface GetCarsData {
  cars: Car[];
}

export interface GetCarData {
  car: Car;
}

export interface GetCarVars {
  id: string;
}

export interface AddCarData {
  addCar: Car;
}

export interface AddCarVars {
  input: AddCarInput;
}

export const GET_CARS = gql`
  query GetCars {
    cars {
      id
      make
      model
      year
      color
      price
      mileage
      status
      description
      createdAt
      updatedAt
    }
  }
`;

export const GET_CAR = gql`
  query GetCar($id: ID!) {
    car(id: $id) {
      id
      make
      model
      year
      color
      price
      mileage
      status
      description
      createdAt
      updatedAt
    }
  }
`;

export const ADD_CAR = gql`
  mutation AddCar($input: AddCarInput!) {
    addCar(input: $input) {
      id
      make
      model
      year
      color
      price
      mileage
      status
      description
      createdAt
      updatedAt
    }
  }
`;

