import {
  Card,
  CardActionArea,
  CardContent,
  Typography,
  Box,
  Chip,
  Stack,
  SxProps,
  Theme,
} from '@mui/material';
import { Car } from '../types/car';
import CarImage from './CarImage';

export interface CarCardProps {
  car: Car;
  onClick?: () => void;
  sx?: SxProps<Theme>;
}

export default function CarCard({ car, onClick, sx }: CarCardProps) {
  const formattedPrice = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(car.price);

  const formattedMileage =
    car.mileage !== undefined && car.mileage !== null
      ? `${car.mileage.toLocaleString()} mi`
      : null;

  const content = (
    <>
      <CarImage
        imageUrl={car.imageUrl}
        alt={`${car.year} ${car.make} ${car.model}`}
        height={200}
        aspectRatio="16/9"
        objectFit="cover"
      />
      <CardContent sx={{ flexGrow: 1, p: 2 }}>
        <Stack spacing={1}>
          <Box display="flex" justifyContent="space-between" alignItems="baseline">
            <Typography variant="h6" component="h2" fontWeight="bold" noWrap>
              {car.year} {car.make} {car.model}
            </Typography>
            <Typography variant="h6" color="primary" fontWeight="bold" sx={{ ml: 1, flexShrink: 0 }}>
              {formattedPrice}
            </Typography>
          </Box>

          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            {car.color && (
              <Chip
                size="small"
                variant="outlined"
                label={car.color}
                icon={
                  <Box
                    component="span"
                    sx={{
                      width: 10,
                      height: 10,
                      borderRadius: '50%',
                      backgroundColor: car.color.toLowerCase(),
                      border: '1px solid rgba(0, 0, 0, 0.2)',
                      display: 'inline-block',
                      ml: '6px !important',
                    }}
                  />
                }
              />
            )}
            {formattedMileage && (
              <Chip size="small" variant="outlined" label={formattedMileage} />
            )}
            {car.vin && (
              <Chip
                size="small"
                variant="outlined"
                label={`VIN: ${car.vin.slice(-6)}`}
              />
            )}
          </Stack>

          {car.description && (
            <Typography
              variant="body2"
              color="text.secondary"
              sx={{
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                mt: 0.5,
              }}
            >
              {car.description}
            </Typography>
          )}
        </Stack>
      </CardContent>
    </>
  );

  return (
    <Card
      sx={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        borderRadius: 2,
        boxShadow: 2,
        transition: 'transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out',
        '&:hover': onClick
          ? {
              transform: 'translateY(-4px)',
              boxShadow: 4,
            }
          : undefined,
        ...sx,
      }}
    >
      {onClick ? (
        <CardActionArea
          onClick={onClick}
          sx={{ display: 'flex', flexDirection: 'column', alignItems: 'stretch', height: '100%' }}
        >
          {content}
        </CardActionArea>
      ) : (
        content
      )}
    </Card>
  );
}

