                  label="Mileage"
                  type="number"
                  value={formData.mileage}
                  onChange={handleChange}
                  error={Boolean(errors.mileage)}
                  helperText={errors.mileage}
                  disabled={addingCar}
                  inputProps={{ min: 0 }}
                  placeholder="e.g. 15000"
                />
              </Grid>

              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  select
                  id="status"
                  name="status"
                  label="Status"
                  value={formData.status}
                  onChange={handleChange}
                  disabled={addingCar}
                >
                  {statusOptions.map((option) => (
                    <MenuItem key={option.value} value={option.value}>
                      {option.label}
                    </MenuItem>
                  ))}
                </TextField>
              </Grid>

              <Grid item xs={12}>
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  id="description"
                  name="description"
                  label="Description"
                  value={formData.description}
                  onChange={handleChange}
                  disabled={addingCar}
