        <source
          media={`(min-width: ${smBreakpoint}px)`}
          srcSet={tabletSrc}
        />
      )}
      {mobileSrc && (
        <source
          media={`(max-width: ${smBreakpoint - 0.05}px)`}
          srcSet={mobileSrc}
        />
      )}
      <Box
        component="img"
        src={defaultImgSrc}
        alt={alt}
        onError={() => setHasError(true)}
        sx={{
          width: '100%',
          height: '100%',
          objectFit,
          aspectRatio,
          borderRadius,
          display: 'block',
        }}
      />
    </Box>
  );
}
"}

