                <Typography variant="subtitle2" color="text.secondary">
                  Model
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {car.model}
                </Typography>
              </Grid>

              <Grid item xs={12} sm={6}>
                <Typography variant="subtitle2" color="text.secondary">
                  Year
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {car.year}
                </Typography>
              </Grid>

              {car.color && (
                <Grid item xs={12} sm={6}>
                  <Typography variant="subtitle2" color="text.secondary">
                    Color
                  </Typography>
                  <Typography variant="body1" fontWeight="medium">
                    {car.color}
                  </Typography>
                </Grid>
              )}

              {car.mileage !== undefined && car.mileage !== null && (
                <Grid item xs={12} sm={6}>
                  <Typography variant="subtitle2" color="text.secondary">
