          </Box>
        )}

        {!loading && !error && !car && (
          <Alert severity="info" sx={{ my: 2 }}>
            No car details found.
          </Alert>
        )}
      </DialogContent>

      <DialogActions sx={{ px: 3, py: 2 }}>
        <Button onClick={onClose} variant="contained" color="primary">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
}

