import { useQuery, useMutation } from '@apollo/client';
import {
  GET_CARS,
  ADD_CAR,
  Car,
  AddCarInput,
  GetCarsData,
  AddCarData,
  AddCarVars,
} from '../graphql/carQueries';

export interface UseCarsResult {
  cars: Car[];
  loading: boolean;
  error: Error | undefined;
  refetch: () => Promise<any>;
  addCar: (input: AddCarInput) => Promise<any>;
  addingCar: boolean;
  addCarLoading: boolean;
  addCarError: Error | undefined;
}

export function useCars(): UseCarsResult {
  const { data, loading, error, refetch } = useQuery<GetCarsData>(GET_CARS);

  const [addCarMutation, { loading: addingCar, error: addCarError }] = useMutation<
    AddCarData,
    AddCarVars
  >(ADD_CAR, {
    refetchQueries: [{ query: GET_CARS }],
    awaitRefetchQueries: true,
  });

  const addCar = async (input: AddCarInput) => {
    return addCarMutation({
      variables: { input },
    });
  };

  return {
    cars: data?.cars ?? [],
    loading,
    error,
    refetch,
    addCar,
    addingCar,
    addCarLoading: addingCar,
    addCarError,
  };
}

export default useCars;

import { useState, useMemo, useCallback } from 'react';
import { Car } from '../types/car';

export type SortField = 'price' | 'year' | 'mileage' | 'make' | 'model' | 'createdAt' | '';
export type SortOrder = 'asc' | 'desc';

export interface UseCarFiltersOptions {
  initialSearch?: string;
  initialYear?: string | number;
  initialSortBy?: SortField;
  initialSortOrder?: SortOrder;
}

export interface UseCarFiltersReturn {
  modelSearch: string;
  search: string;
  searchTerm: string;
  setModelSearch: (value: string) => void;
  setSearch: (value: string) => void;
  setSearchTerm: (value: string) => void;
  yearFilter: string | number;
  selectedYear: string | number;
  setYearFilter: (value: string | number) => void;
  setSelectedYear: (value: string | number) => void;
  sortBy: SortField;
  setSortBy: (field: SortField) => void;
  sortOrder: SortOrder;
  setSortOrder: (order: SortOrder) => void;
  sortOption: string;
  setSortOption: (option: string) => void;
  filteredCars: Car[];
  availableYears: number[];
  resetFilters: () => void;
}

export function useCarFilters(
  cars: Car[] = [],
  options: UseCarFiltersOptions = {}
): UseCarFiltersReturn {
  const {
    initialSearch = '',
    initialYear = '',
    initialSortBy = '',
    initialSortOrder = 'asc',
  } = options;

  const [modelSearch, setModelSearch] = useState<string>(initialSearch);
  const [yearFilter, setYearFilter] = useState<string | number>(initialYear);
  const [sortBy, setSortBy] = useState<SortField>(initialSortBy);
  const [sortOrder, setSortOrder] = useState<SortOrder>(initialSortOrder);

  const availableYears = useMemo(() => {
    if (!cars || cars.length === 0) return [];
    const years = Array.from(
      new Set(cars.map((car) => car.year).filter((year) => typeof year === 'number' && !isNaN(year)))
    );
    return years.sort((a, b) => b - a);
  }, [cars]);

  const filteredCars = useMemo(() => {
    if (!cars) return [];

    let result = [...cars];

    // Filter by model / search term
    if (modelSearch.trim()) {
      const query = modelSearch.trim().toLowerCase();
      result = result.filter((car) => {
        const modelMatch = car.model?.toLowerCase().includes(query);
        const makeMatch = car.make?.toLowerCase().includes(query);
        const fullMatch = `${car.make ?? ''} ${car.model ?? ''}`.toLowerCase().includes(query);
        return modelMatch || makeMatch || fullMatch;
      });
    }

    // Filter by year
    if (yearFilter !== '' && yearFilter !== 'all' && yearFilter !== 'ALL') {
      const yearNum = Number(yearFilter);
      if (!isNaN(yearNum)) {
        result = result.filter((car) => car.year === yearNum);
      }
    }

    // Sorting
    if (sortBy) {
      result.sort((a, b) => {
        let comparison = 0;
        switch (sortBy) {
          case 'price':
            comparison = (a.price ?? 0) - (b.price ?? 0);
            break;
          case 'year':
            comparison = (a.year ?? 0) - (b.year ?? 0);
            break;
          case 'mileage':
            comparison = (a.mileage ?? 0) - (b.mileage ?? 0);
            break;
          case 'make':
            comparison = (a.make ?? '').localeCompare(b.make ?? '');
            break;
          case 'model':
            comparison = (a.model ?? '').localeCompare(b.model ?? '');
            break;
          case 'createdAt':
            comparison = new Date(a.createdAt ?? 0).getTime() - new Date(b.createdAt ?? 0).getTime();
            break;
          default:
            comparison = 0;
        }
        return sortOrder === 'desc' ? -comparison : comparison;
      });
    }

    return result;
  }, [cars, modelSearch, yearFilter, sortBy, sortOrder]);

  const sortOption = useMemo(() => {
    if (!sortBy) return '';
    return `${sortBy}_${sortOrder}`;
  }, [sortBy, sortOrder]);

  const setSortOption = useCallback((option: string) => {
    if (!option || option === 'none' || option === '') {
      setSortBy('');
      setSortOrder('asc');
      return;
    }

    const separator = option.includes('-') ? '-' : '_';
    const parts = option.split(separator);
    const order = parts[parts.length - 1]?.toLowerCase();
    const field = parts.slice(0, parts.length - 1).join('_') as SortField;

    if (order === 'asc' || order === 'desc') {
      setSortBy(field);
      setSortOrder(order);
    } else {
      setSortBy(option as SortField);
      setSortOrder('asc');
    }
  }, []);

  const resetFilters = useCallback(() => {
    setModelSearch(initialSearch);
    setYearFilter(initialYear);
    setSortBy(initialSortBy);
    setSortOrder(initialSortOrder);
  }, [initialSearch, initialYear, initialSortBy, initialSortOrder]);

  return {
    modelSearch,
    search: modelSearch,
    searchTerm: modelSearch,
    setModelSearch,
    setSearch: setModelSearch,
    setSearchTerm: setModelSearch,
    yearFilter,
    selectedYear: yearFilter,
    setYearFilter,
    setSelectedYear: setYearFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    sortOption,
    setSortOption,
    filteredCars,
    availableYears,
    resetFilters,
  };
}

export default useCarFilters;

import React from 'react';
import {
  Card,
  CardActionArea,
  CardContent,
  Typography,
  Box,
  Chip,
  Stack,
  SxProps,
  Theme,
} from '@mui/material';
import { Car } from '../types/car';
import CarImage from './CarImage';

export interface CarCardProps {
  car: Car;
  onClick?: () => void;
  sx?: SxProps<Theme>;
}

export default function CarCard({ car, onClick, sx }: CarCardProps) {
  const formattedPrice = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(car.price);

  const formattedMileage =
    car.mileage !== undefined && car.mileage !== null
      ? `${car.mileage.toLocaleString()} mi`
      : null;

  const content = (
    <>
      <CarImage
        imageUrl={car.imageUrl}
        alt={`${car.year} ${car.make} ${car.model}`}
        height={200}
        aspectRatio="16/9"
        objectFit="cover"
      />
      <CardContent sx={{ flexGrow: 1, p: 2 }}>
        <Stack spacing={1}>
          <Box display="flex" justifyContent="space-between" alignItems="baseline">
            <Typography variant="h6" component="h2" fontWeight="bold" noWrap>
              {car.year} {car.make} {car.model}
            </Typography>
            <Typography variant="h6" color="primary" fontWeight="bold" sx={{ ml: 1, flexShrink: 0 }}>
              {formattedPrice}
            </Typography>
          </Box>

          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            {car.color && (
              <Chip
                size="small"
                variant="outlined"
                label={car.color}
                icon={
                  <Box
                    component="span"
                    sx={{
                      width: 10,
                      height: 10,
                      borderRadius: '50%',
                      backgroundColor: car.color.toLowerCase(),
                      border: '1px solid rgba(0, 0, 0, 0.2)',
                      display: 'inline-block',
                      ml: '6px !important',
                    }}
                  />
                }
              />
            )}
            {formattedMileage && (
              <Chip size="small" variant="outlined" label={formattedMileage} />
            )}
            {car.vin && (
              <Chip
                size="small"
                variant="outlined"
                label={`VIN: ${car.vin.slice(-6)}`}
              />
            )}
          </Stack>

          {car.description && (
            <Typography
              variant="body2"
              color="text.secondary"
              sx={{
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                mt: 0.5,
              }}
            >
              {car.description}
            </Typography>
          )}
        </Stack>
      </CardContent>
    </>
  );

  return (
    <Card
      sx={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        borderRadius: 2,
        boxShadow: 2,
        transition: 'transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out',
        '&:hover': onClick
          ? {
              transform: 'translateY(-4px)',
              boxShadow: 4,
            }
          : undefined,
        ...sx,
      }}
    >
      {onClick ? (
        <CardActionArea
          onClick={onClick}
          sx={{ display: 'flex', flexDirection: 'column', alignItems: 'stretch', height: '100%' }}
        >
          {content}
        </CardActionArea>
      ) : (
        content
      )}
    </Card>
  );
}

import React from 'react';
import {
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Button,
  Grid,
  SelectChangeEvent,
} from '@mui/material';
import { SortField, SortOrder } from '../hooks/useCarFilters';

export interface CarFiltersProps {
  modelSearch?: string;
  search?: string;
  searchTerm?: string;
  onModelSearchChange?: (value: string) => void;
  onSearchChange?: (value: string) => void;
  setModelSearch?: (value: string) => void;
  setSearch?: (value: string) => void;
  setSearchTerm?: (value: string) => void;

  yearFilter?: string | number;
  selectedYear?: string | number;
  onYearChange?: (value: string | number) => void;
  setYearFilter?: (value: string | number) => void;
  setSelectedYear?: (value: string | number) => void;
  availableYears?: number[];

  sortBy?: SortField;
  setSortBy?: (field: SortField) => void;
  sortOrder?: SortOrder;
  setSortOrder?: (order: SortOrder) => void;
  sortOption?: string;
  setSortOption?: (option: string) => void;
  onSortChange?: (field: SortField, order: SortOrder) => void;

  resetFilters?: () => void;
  onReset?: () => void;
}

export default function CarFilters({
  modelSearch,
  search,
  searchTerm,
  onModelSearchChange,
  onSearchChange,
  setModelSearch,
  setSearch,
  setSearchTerm,

  yearFilter,
  selectedYear,
  onYearChange,
  setYearFilter,
  setSelectedYear,
  availableYears = [],

  sortBy = '',
  setSortBy,
  sortOrder = 'asc',
  setSortOrder,
  sortOption,
  setSortOption,
  onSortChange,

  resetFilters,
  onReset,
}: CarFiltersProps) {
  const currentSearchValue = modelSearch ?? search ?? searchTerm ?? '';
  const currentYearValue = yearFilter ?? selectedYear ?? '';
  const currentSortValue =
    sortOption ?? (sortBy ? `${sortBy}_${sortOrder}` : '');

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    onModelSearchChange?.(value);
    onSearchChange?.(value);
    setModelSearch?.(value);
    setSearch?.(value);
    setSearchTerm?.(value);
  };

  const handleYearChange = (e: SelectChangeEvent<string | number>) => {
    const value = e.target.value;
    onYearChange?.(value);
    setYearFilter?.(value);
    setSelectedYear?.(value);
  };

  const handleSortChange = (e: SelectChangeEvent<string>) => {
    const value = e.target.value;
    if (setSortOption) {
      setSortOption(value);
    }
    if (!value) {
      setSortBy?.('');
      setSortOrder?.('asc');
      onSortChange?.('', 'asc');
    } else {
      const parts = value.split('_');
      const order = (parts[parts.length - 1] ?? 'asc') as SortOrder;
      const field = parts.slice(0, parts.length - 1).join('_') as SortField;
      setSortBy?.(field);
      setSortOrder?.(order);
      onSortChange?.(field, order);
    }
  };

  const handleReset = () => {
    resetFilters?.();
    onReset?.();
  };

  return (
    <Box sx={{ mb: 3 }}>
      <Grid container spacing={2} alignItems="center">
        <Grid item xs={12} sm={4} md={4}>
          <TextField
            fullWidth
            size="small"
            label="Search Make or Model"
            placeholder="e.g. Toyota, Civic..."
            value={currentSearchValue}
            onChange={handleSearchChange}
