import { useQuery, useMutation } from '@apollo/client';
import {
  GET_CARS,
  ADD_CAR,
  Car,
  AddCarInput,
  GetCarsData,
  AddCarData,
  AddCarVars,
} from '../graphql/carQueries';

export interface UseCarsResult {
  cars: Car[];
  loading: boolean;
  error: Error | undefined;
  refetch: () => Promise<any>;
  addCar: (input: AddCarInput) => Promise<any>;
  addingCar: boolean;
  addCarLoading: boolean;
  addCarError: Error | undefined;
}

export function useCars(): UseCarsResult {
  const { data, loading, error, refetch } = useQuery<GetCarsData>(GET_CARS);

  const [addCarMutation, { loading: addingCar, error: addCarError }] = useMutation<
    AddCarData,
    AddCarVars
  >(ADD_CAR, {
    refetchQueries: [{ query: GET_CARS }],
    awaitRefetchQueries: true,
  });

  const addCar = async (input: AddCarInput) => {
    return addCarMutation({
      variables: { input },
    });
  };

  return {
    cars: data?.cars ?? [],
    loading,
    error,
    refetch,
    addCar,
    addingCar,
    addCarLoading: addingCar,
    addCarError,
  };
}

export default useCars;


