import {
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Button,
  Grid,
  SelectChangeEvent,
} from '@mui/material';
import { SortField, SortOrder } from '../hooks/useCarFilters';

export interface CarFiltersProps {
  modelSearch?: string;
  search?: string;
  searchTerm?: string;
  onModelSearchChange?: (value: string) => void;
  onSearchChange?: (value: string) => void;
  setModelSearch?: (value: string) => void;
  setSearch?: (value: string) => void;
  setSearchTerm?: (value: string) => void;

  yearFilter?: string | number;
  selectedYear?: string | number;
  onYearChange?: (value: string | number) => void;
  setYearFilter?: (value: string | number) => void;
  setSelectedYear?: (value: string | number) => void;
  availableYears?: number[];

  sortBy?: SortField;
  setSortBy?: (field: SortField) => void;
  sortOrder?: SortOrder;
  setSortOrder?: (order: SortOrder) => void;
  sortOption?: string;
  setSortOption?: (option: string) => void;
  onSortChange?: (field: SortField, order: SortOrder) => void;

  resetFilters?: () => void;
  onReset?: () => void;
}

export default function CarFilters({
  modelSearch,
  search,
  searchTerm,
  onModelSearchChange,
  onSearchChange,
  setModelSearch,
  setSearch,
  setSearchTerm,

  yearFilter,
  selectedYear,
  onYearChange,
  setYearFilter,
  setSelectedYear,
  availableYears = [],

  sortBy = '',
  setSortBy,
  sortOrder = 'asc',
  setSortOrder,
  sortOption,
  setSortOption,
  onSortChange,

  resetFilters,
  onReset,
}: CarFiltersProps) {
  const currentSearchValue = modelSearch ?? search ?? searchTerm ?? '';
  const currentYearValue = yearFilter ?? selectedYear ?? '';
  const currentSortValue =
    sortOption ?? (sortBy ? `${sortBy}_${sortOrder}` : '');

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    onModelSearchChange?.(value);
    onSearchChange?.(value);
    setModelSearch?.(value);
    setSearch?.(value);
    setSearchTerm?.(value);
  };

  const handleYearChange = (e: SelectChangeEvent<string | number>) => {
    const value = e.target.value;
    onYearChange?.(value);
    setYearFilter?.(value);
    setSelectedYear?.(value);
  };

  const handleSortChange = (e: SelectChangeEvent<string>) => {
    const value = e.target.value;
    if (setSortOption) {
      setSortOption(value);
    }
    if (!value) {
      setSortBy?.('');
      setSortOrder?.('asc');
      onSortChange?.('', 'asc');
    } else {
      const parts = value.split('_');
      const order = (parts[parts.length - 1] ?? 'asc') as SortOrder;
      const field = parts.slice(0, parts.length - 1).join('_') as SortField;
      setSortBy?.(field);
      setSortOrder?.(order);
      onSortChange?.(field, order);
    }
  };

  const handleReset = () => {
    resetFilters?.();
    onReset?.();
  };

  return (
    <Box sx={{ mb: 3 }}>
      <Grid container spacing={2} alignItems="center">
        <Grid item xs={12} sm={4} md={4}>
          <TextField
            fullWidth
            size="small"
            label="Search Make or Model"
            placeholder="e.g. Toyota, Civic..."
            value={currentSearchValue}
            onChange={handleSearchChange}
            inputProps={{ 'aria-label': 'Search model or make' }}
          />
        </Grid>

        <Grid item xs={12} sm={3} md={3}>
          <FormControl fullWidth size="small">
            <InputLabel id="car-year-filter-label">Year</InputLabel>
            <Select
              labelId="car-year-filter-label"
              id="car-year-filter-select"
              value={currentYearValue}
              label="Year"
              onChange={handleYearChange}
            >
              <MenuItem value="">
                <em>All Years</em>
              </MenuItem>
              {availableYears.map((year) => (
                <MenuItem key={year} value={year}>
                  {year}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12} sm={3} md={3}>
          <FormControl fullWidth size="small">
            <InputLabel id="car-sort-filter-label">Sort By</InputLabel>
            <Select
              labelId="car-sort-filter-label"
              id="car-sort-filter-select"
              value={currentSortValue}
              label="Sort By"
              onChange={handleSortChange}
            >
              <MenuItem value="">
                <em>Default</em>
              </MenuItem>
              <MenuItem value="price_asc">Price: Low to High</MenuItem>
              <MenuItem value="price_desc">Price: High to Low</MenuItem>
              <MenuItem value="year_desc">Year: Newest First</MenuItem>
              <MenuItem value="year_asc">Year: Oldest First</MenuItem>
              <MenuItem value="mileage_asc">Mileage: Low to High</MenuItem>
              <MenuItem value="mileage_desc">Mileage: High to Low</MenuItem>
              <MenuItem value="make_asc">Make: A to Z</MenuItem>
              <MenuItem value="make_desc">Make: Z to A</MenuItem>
              <MenuItem value="model_asc">Model: A to Z</MenuItem>
              <MenuItem value="model_desc">Model: Z to A</MenuItem>
            </Select>
          </FormControl>
        </Grid>

        <Grid item xs={12} sm={2} md={2}>
          <Button
            fullWidth
            variant="outlined"
            color="secondary"
            onClick={handleReset}
            sx={{ height: 40 }}
          >
            Reset
          </Button>
        </Grid>
      </Grid>
    </Box>
  );
}
"}

