import { useState, useMemo, useCallback } from 'react';
import { Car } from '../types/car';

export type SortField = 'price' | 'year' | 'mileage' | 'make' | 'model' | 'createdAt' | '';
export type SortOrder = 'asc' | 'desc';

export interface UseCarFiltersOptions {
  initialSearch?: string;
  initialYear?: string | number;
  initialSortBy?: SortField;
  initialSortOrder?: SortOrder;
}

export interface UseCarFiltersReturn {
  modelSearch: string;
  search: string;
  searchTerm: string;
  setModelSearch: (value: string) => void;
  setSearch: (value: string) => void;
  setSearchTerm: (value: string) => void;
  yearFilter: string | number;
  selectedYear: string | number;
  setYearFilter: (value: string | number) => void;
  setSelectedYear: (value: string | number) => void;
  sortBy: SortField;
  setSortBy: (field: SortField) => void;
  sortOrder: SortOrder;
  setSortOrder: (order: SortOrder) => void;
  sortOption: string;
  setSortOption: (option: string) => void;
  filteredCars: Car[];
  availableYears: number[];
  resetFilters: () => void;
}

export function useCarFilters(
  cars: Car[] = [],
  options: UseCarFiltersOptions = {}
): UseCarFiltersReturn {
  const {
    initialSearch = '',
    initialYear = '',
    initialSortBy = '',
    initialSortOrder = 'asc',
  } = options;

  const [modelSearch, setModelSearch] = useState<string>(initialSearch);
  const [yearFilter, setYearFilter] = useState<string | number>(initialYear);
  const [sortBy, setSortBy] = useState<SortField>(initialSortBy);
  const [sortOrder, setSortOrder] = useState<SortOrder>(initialSortOrder);

  const availableYears = useMemo(() => {
    if (!cars || cars.length === 0) return [];
    const years = Array.from(
      new Set(cars.map((car) => car.year).filter((year) => typeof year === 'number' && !isNaN(year)))
    );
    return years.sort((a, b) => b - a);
  }, [cars]);

  const filteredCars = useMemo(() => {
    if (!cars) return [];

    let result = [...cars];

    // Filter by model / search term
    if (modelSearch.trim()) {
      const query = modelSearch.trim().toLowerCase();
      result = result.filter((car) => {
        const modelMatch = car.model?.toLowerCase().includes(query);
        const makeMatch = car.make?.toLowerCase().includes(query);
        const fullMatch = `${car.make ?? ''} ${car.model ?? ''}`.toLowerCase().includes(query);
        return modelMatch || makeMatch || fullMatch;
      });
    }

    // Filter by year
    if (yearFilter !== '' && yearFilter !== 'all' && yearFilter !== 'ALL') {
      const yearNum = Number(yearFilter);
      if (!isNaN(yearNum)) {
        result = result.filter((car) => car.year === yearNum);
      }
    }

    // Sorting
    if (sortBy) {
      result.sort((a, b) => {
        let comparison = 0;
        switch (sortBy) {
          case 'price':
            comparison = (a.price ?? 0) - (b.price ?? 0);
            break;
          case 'year':
            comparison = (a.year ?? 0) - (b.year ?? 0);
            break;
          case 'mileage':
            comparison = (a.mileage ?? 0) - (b.mileage ?? 0);
            break;
          case 'make':
            comparison = (a.make ?? '').localeCompare(b.make ?? '');
            break;
          case 'model':
            comparison = (a.model ?? '').localeCompare(b.model ?? '');
            break;
          case 'createdAt':
            comparison = new Date(a.createdAt ?? 0).getTime() - new Date(b.createdAt ?? 0).getTime();
            break;
          default:
            comparison = 0;
        }
        return sortOrder === 'desc' ? -comparison : comparison;
      });
    }

    return result;
  }, [cars, modelSearch, yearFilter, sortBy, sortOrder]);

  const sortOption = useMemo(() => {
    if (!sortBy) return '';
    return `${sortBy}_${sortOrder}`;
  }, [sortBy, sortOrder]);

  const setSortOption = useCallback((option: string) => {
    if (!option || option === 'none' || option === '') {
      setSortBy('');
      setSortOrder('asc');
      return;
    }

    const separator = option.includes('-') ? '-' : '_';
    const parts = option.split(separator);
    const order = parts[parts.length - 1]?.toLowerCase();
    const field = parts.slice(0, parts.length - 1).join('_') as SortField;

    if (order === 'asc' || order === 'desc') {
      setSortBy(field);
      setSortOrder(order);
    } else {
      setSortBy(option as SortField);
      setSortOrder('asc');
    }
  }, []);

  const resetFilters = useCallback(() => {
    setModelSearch(initialSearch);
    setYearFilter(initialYear);
    setSortBy(initialSortBy);
    setSortOrder(initialSortOrder);
  }, [initialSearch, initialYear, initialSortBy, initialSortOrder]);

  return {
    modelSearch,
    search: modelSearch,
    searchTerm: modelSearch,
    setModelSearch,
    setSearch: setModelSearch,
    setSearchTerm: setModelSearch,
    yearFilter,
    selectedYear: yearFilter,
    setYearFilter,
    setSelectedYear: setYearFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    sortOption,
    setSortOption,
    filteredCars,
    availableYears,
    resetFilters,
  };
}

export default useCarFilters;


