import React from 'react';
import {
  Card,
  CardActionArea,
  CardContent,
  Typography,
  Box,
  Chip,
  Stack,
  SxProps,
  Theme,
} from '@mui/material';
import { Car } from '../types/car';
import CarImage from './CarImage';

export interface CarCardProps {
  car: Car;
  onClick?: () => void;
  sx?: SxProps<Theme>;
}

export default function CarCard({ car, onClick, sx }: CarCardProps) {
  const formattedPrice = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(car.price);

  const formattedMileage =
    car.mileage !== undefined && car.mileage !== null
      ? `${car.mileage.toLocaleString()} mi`
      : null;

  const content = (
    <>
      <CarImage
        imageUrl={car.imageUrl}
        alt={`${car.year} ${car.make} ${car.model}`}
        height={200}
        aspectRatio="16/9"
        objectFit="cover"
      />
      <CardContent sx={{ flexGrow: 1, p: 2 }}>
        <Stack spacing={1}>
          <Box display="flex" justifyContent="space-between" alignItems="baseline">
            <Typography variant="h6" component="h2" fontWeight="bold" noWrap>
              {car.year} {car.make} {car.model}
            </Typography>
            <Typography variant="h6" color="primary" fontWeight="bold" sx={{ ml: 1, flexShrink: 0 }}>
              {formattedPrice}
            </Typography>
          </Box>

          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            {car.color && (
              <Chip
                size="small"
                variant="outlined"
                label={car.color}
                icon={
                  <Box
                    component="span"
                    sx={{
                      width: 10,
                      height: 10,
                      borderRadius: '50%',
                      backgroundColor: car.color.toLowerCase(),
                      border: '1px solid rgba(0, 0, 0, 0.2)',
                      display: 'inline-block',
                      ml: '6px !important',
                    }}
                  />
                }
              />
            )}
            {formattedMileage && (
              <Chip size="small" variant="outlined" label={formattedMileage} />
            )}
            {car.vin && (
              <Chip
                size="small"
                variant="outlined"
                label={`VIN: ${car.vin.slice(-6)}`}
              />
            )}
          </Stack>

          {car.description && (
            <Typography
              variant="body2"
              color="text.secondary"
              sx={{
                display: '-webkit-box',
                WebkitLineClamp: 2,
                WebkitBoxOrient: 'vertical',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                mt: 0.5,
              }}
            >
              {car.description}
            </Typography>
          )}
        </Stack>
      </CardContent>
    </>
  );

  return (
    <Card
      sx={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        borderRadius: 2,
        boxShadow: 2,
        transition: 'transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out',
        '&:hover': onClick
          ? {
              transform: 'translateY(-4px)',
              boxShadow: 4,
            }
          : undefined,
        ...sx,
      }}
    >
      {onClick ? (
        <CardActionArea
          onClick={onClick}
          sx={{ display: 'flex', flexDirection: 'column', alignItems: 'stretch', height: '100%' }}
        >
          {content}
        </CardActionArea>
      ) : (
        content
      )}
    </Card>
  );
}

import React, { useState } from 'react';
import {
  Box,
  Grid,
  CircularProgress,
  Alert,
  Typography,
  Button,
  Stack,
} from '@mui/material';
import { Car } from '../types/car';
import useCars from '../hooks/useCars';
import useCarFilters from '../hooks/useCarFilters';
import CarCard from './CarCard';
import CarFilters from './CarFilters';
import CarDetailsModal from './CarDetailsModal';

export interface CarListProps {
  onCarSelect?: (car: Car) => void;
}

export default function CarList({ onCarSelect }: CarListProps) {
  const { cars, loading, error, refetch } = useCars();
  const [selectedCarId, setSelectedCarId] = useState<string | null>(null);
  const [modalOpen, setModalOpen] = useState(false);

  const {
    modelSearch,
    setModelSearch,
    yearFilter,
    setYearFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    sortOption,
    setSortOption,
    filteredCars,
    availableYears,
    resetFilters,
  } = useCarFilters(cars);

  const handleCarClick = (car: Car) => {
    setSelectedCarId(car.id);
    setModalOpen(true);
    onCarSelect?.(car);
  };

  const handleCloseModal = () => {
    setModalOpen(false);
    setSelectedCarId(null);
  };

  return (
    <Box sx={{ width: '100%', py: 2 }}>
      <CarFilters
        modelSearch={modelSearch}
        setModelSearch={setModelSearch}
        yearFilter={yearFilter}
        setYearFilter={setYearFilter}
        availableYears={availableYears}
        sortBy={sortBy}
        setSortBy={setSortBy}
        sortOrder={sortOrder}
        setSortOrder={setSortOrder}
        sortOption={sortOption}
        setSortOption={setSortOption}
        resetFilters={resetFilters}
      />

      {loading && (
        <Box
          display="flex"
          justifyContent="center"
          alignItems="center"
          minHeight="300px"
        >
          <CircularProgress />
        </Box>
      )}

      {error && !loading && (
        <Alert
          severity="error"
          sx={{ my: 3 }}
          action={
            <Button color="inherit" size="small" onClick={() => refetch()}>
              Retry
            </Button>
          }
        >
          {error.message || 'Failed to load cars. Please try again.'}
        </Alert>
      )}

      {!loading && !error && filteredCars.length === 0 && (
        <Box
          sx={{
            textAlign: 'center',
            py: 8,
            px: 2,
            backgroundColor: 'background.paper',
            borderRadius: 2,
            border: '1px dashed',
            borderColor: 'divider',
          }}
        >
          <Typography variant="h6" color="text.secondary" gutterBottom>
            No cars found
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {cars.length === 0
              ? 'There are currently no cars in the inventory.'
              : 'No cars match your search and filter criteria. Try adjusting your filters.'}
          </Typography>
          {cars.length > 0 && (
            <Button variant="outlined" color="primary" onClick={resetFilters}>
              Reset Filters
            </Button>
          )}
        </Box>
      )}

      {!loading && !error && filteredCars.length > 0 && (
        <>
          <Box sx={{ mb: 2 }}>
            <Typography variant="body2" color="text.secondary">
              Showing {filteredCars.length} {filteredCars.length === 1 ? 'car' : 'cars'}
            </Typography>
          </Box>
          <Grid container spacing={3}>
            {filteredCars.map((car) => (
              <Grid item key={car.id} xs={12} sm={6} md={4} lg={4}>
                <CarCard car={car} onClick={() => handleCarClick(car)} />
              </Grid>
            ))}
          </Grid>
        </>
      )}

      <CarDetailsModal
        carId={selectedCarId}
