import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import CarCard from '../CarCard';
import { Car } from '../../types/car';

const mockCar: Car = {
  id: '1',
  make: 'Toyota',
  model: 'Camry',
  year: 2022,
  price: 24500,
  mileage: 15230,
  color: 'Blue',
  vin: '1HGCR2F83HA123456',
  description: 'A well-maintained sedan in excellent condition with low mileage.',
  imageUrl: 'https://example.com/camry.jpg',
};

describe('CarCard', () => {
  it('renders car title with year, make, and model', () => {
    render(<CarCard car={mockCar} />);

    expect(screen.getByRole('heading', { level: 2 })).toHaveTextContent('2022 Toyota Camry');
  });

  it('formats and renders price in USD currency', () => {
    render(<CarCard car={mockCar} />);

    expect(screen.getByText('$24,500')).toBeInTheDocument();
  });

  it('renders formatted mileage with commas and unit', () => {
    render(<CarCard car={mockCar} />);

    expect(screen.getByText('15,230 mi')).toBeInTheDocument();
  });

  it('renders color chip when color is provided', () => {
    render(<CarCard car={mockCar} />);

    expect(screen.getByText('Blue')).toBeInTheDocument();
  });

  it('renders VIN chip displaying the last 6 characters', () => {
    render(<CarCard car={mockCar} />);

    expect(screen.getByText('VIN: 123456')).toBeInTheDocument();
  });

  it('renders description text', () => {
    render(<CarCard car={mockCar} />);

    expect(
      screen.getByText('A well-maintained sedan in excellent condition with low mileage.')
    ).toBeInTheDocument();
  });

  it('renders car image with proper alt text', () => {
    render(<CarCard car={mockCar} />);

    const image = screen.getByAltText('2022 Toyota Camry');
    expect(image).toBeInTheDocument();
  });

  it('calls onClick handler when card is clicked', async () => {
    const user = userEvent.setup();
    const handleClick = jest.fn();

    render(<CarCard car={mockCar} onClick={handleClick} />);

    const cardButton = screen.getByRole('button');
