import React, { useState } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  CardHeader,
  CircularProgress,
  Grid,
  MenuItem,
  TextField,
  Alert,
  Stack,
} from '@mui/material';
import useCars from '../hooks/useCars';
import { AddCarInput } from '../graphql/carQueries';

export interface AddCarFormProps {
  onSuccess?: () => void;
  onCancel?: () => void;
}

interface FormState {
  make: string;
  model: string;
  year: string;
  price: string;
  color: string;
  mileage: string;
  status: string;
  description: string;
}

interface FormErrors {
  make?: string;
  model?: string;
  year?: string;
  price?: string;
  mileage?: string;
}

const initialFormState: FormState = {
  make: '',
  model: '',
  year: new Date().getFullYear().toString(),
  price: '',
  color: '',
  mileage: '',
  status: 'AVAILABLE',
  description: '',
};

const statusOptions = [
  { value: 'AVAILABLE', label: 'Available' },
  { value: 'PENDING', label: 'Pending' },
  { value: 'SOLD', label: 'Sold' },
];

export default function AddCarForm({ onSuccess, onCancel }: AddCarFormProps) {
  const { addCar, addingCar, addCarError } = useCars();
  const [formData, setFormData] = useState<FormState>(initialFormState);
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const validate = (): boolean => {
    const newErrors: FormErrors = {};
    const currentYear = new Date().getFullYear();

    if (!formData.make.trim()) {
      newErrors.make = 'Make is required';
    }

    if (!formData.model.trim()) {
      newErrors.model = 'Model is required';
    }

    const yearNum = Number(formData.year);
    if (!formData.year.trim()) {
      newErrors.year = 'Year is required';
    } else if (isNaN(yearNum) || yearNum < 1886 || yearNum > currentYear + 1) {
      newErrors.year = `Enter a valid year between 1886 and ${currentYear + 1}`;
    }

    const priceNum = Number(formData.price);
    if (!formData.price.trim()) {
      newErrors.price = 'Price is required';
    } else if (isNaN(priceNum) || priceNum < 0) {
      newErrors.price = 'Price must be a non-negative number';
    }

    if (formData.mileage.trim()) {
      const mileageNum = Number(formData.mileage);
      if (isNaN(mileageNum) || mileageNum < 0) {
        newErrors.mileage = 'Mileage must be a non-negative number';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));

    if (errors[name as keyof FormErrors]) {
      setErrors((prev) => ({ ...prev, [name]: undefined }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitError(null);
    setSuccessMessage(null);

    if (!validate()) {
      return;
    }

    const input: AddCarInput = {
      make: formData.make.trim(),
      model: formData.model.trim(),
      year: Number(formData.year),
      price: Number(formData.price),
      color: formData.color.trim() || undefined,
      mileage: formData.mileage.trim() ? Number(formData.mileage) : undefined,
      status: formData.status || undefined,
      description: formData.description.trim() || undefined,
    };

    try {
      await addCar(input);
      setSuccessMessage('Car added successfully!');
      setFormData(initialFormState);
      setErrors({});
      if (onSuccess) {
        onSuccess();
      }
    } catch (err: any) {
      setSubmitError(err.message || 'Failed to add car. Please try again.');
    }
  };

  const handleReset = () => {
    setFormData(initialFormState);
    setErrors({});
    setSubmitError(null);
    setSuccessMessage(null);
    if (onCancel) {
      onCancel();
    }
  };

  return (
    <Card elevation={3}>
      <CardHeader title="Add New Car" subheader="Enter vehicle details to add to inventory" />
      <CardContent>
        <Box component="form" onSubmit={handleSubmit} noValidate>
          <Stack spacing={3}>
            {submitError && <Alert severity="error">{submitError}</Alert>}
            {addCarError && !submitError && (
              <Alert severity="error">{addCarError.message}</Alert>
            )}
            {successMessage && <Alert severity="success">{successMessage}</Alert>}

            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  id="make"
                  name="make"
                  label="Make"
                  value={formData.make}
                  onChange={handleChange}
                  error={Boolean(errors.make)}
                  helperText={errors.make}
                  disabled={addingCar}
                  placeholder="e.g. Toyota"
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  id="model"
                  name="model"
                  label="Model"
                  value={formData.model}
                  onChange={handleChange}
                  error={Boolean(errors.model)}
                  helperText={errors.model}
                  disabled={addingCar}
                  placeholder="e.g. Camry"
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  id="year"
                  name="year"
                  label="Year"
                  type="number"
                  value={formData.year}
                  onChange={handleChange}
                  error={Boolean(errors.year)}
                  helperText={errors.year}
                  disabled={addingCar}
                  inputProps={{ min: 1886, max: new Date().getFullYear() + 1 }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  id="price"
                  name="price"
                  label="Price ($)"
                  type="number"
                  value={formData.price}
                  onChange={handleChange}
                  error={Boolean(errors.price)}
                  helperText={errors.price}
                  disabled={addingCar}
                  inputProps={{ min: 0, step: '0.01' }}
                  placeholder="e.g. 24999"
                />
              </Grid>

              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  id="color"
                  name="color"
                  label="Color"
                  value={formData.color}
                  onChange={handleChange}
                  disabled={addingCar}
                  placeholder="e.g. Silver"
                />
              </Grid>

              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  id="mileage"
                  name="mileage"
                  label="Mileage"
                  type="number"
                  value={formData.mileage}
                  onChange={handleChange}
                  error={Boolean(errors.mileage)}
                  helperText={errors.mileage}
                  disabled={addingCar}
                  inputProps={{ min: 0 }}
                  placeholder="e.g. 15000"
                />
              </Grid>

              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  select
                  id="status"
                  name="status"
                  label="Status"
                  value={formData.status}
                  onChange={handleChange}
                  disabled={addingCar}
                >
                  {statusOptions.map((option) => (
                    <MenuItem key={option.value} value={option.value}>
                      {option.label}
                    </MenuItem>
                  ))}
                </TextField>
              </Grid>

              <Grid item xs={12}>
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  id="description"
                  name="description"
                  label="Description"
                  value={formData.description}
                  onChange={handleChange}
                  disabled={addingCar}
                  placeholder="Enter additional details about the vehicle..."
                />
              </Grid>
            </Grid>

            <Stack direction="row" spacing={2} justifyContent="flex-end">
              <Button
                type="button"
                variant="outlined"
                color="secondary"
                onClick={handleReset}
                disabled={addingCar}
              >
                {onCancel ? 'Cancel' : 'Reset'}
              </Button>
              <Button
                type="submit"
                variant="contained"
                color="primary"
                disabled={addingCar}
                startIcon={addingCar ? <CircularProgress size={20} color="inherit" /> : null}
              >
                {addingCar ? 'Adding Car...' : 'Add Car'}
              </Button>
            </Stack>
          </Stack>
        </Box>
      </CardContent>
    </Card>
  );
}

