import React, { useState } from 'react';
import { Box, SxProps, Theme, useTheme } from '@mui/material';

export interface ResponsiveImageSources {
  mobile?: string;
  tablet?: string;
  desktop?: string;
}

export interface CarImageProps {
  src?: string;
  imageUrl?: string;
  images?: ResponsiveImageSources;
  alt?: string;
  height?: number | string;
  width?: number | string;
  objectFit?: 'cover' | 'contain' | 'fill' | 'none' | 'scale-down';
  aspectRatio?: string | number;
  borderRadius?: number | string;
  sx?: SxProps<Theme>;
  className?: string;
}

const DEFAULT_PLACEHOLDER =
  'data:image/svg+xml;charset=UTF-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20800%20450%22%20width%3D%22800%22%20height%3D%22450%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23e0e0e0%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20fill%3D%22%239e9e9e%22%20font-family%3D%22sans-serif%22%20font-size%3D%2224%22%20text-anchor%3D%22middle%22%20dy%3D%22.3em%22%3ENo%20Image%20Available%3C%2Ftext%3E%3C%2Fsvg%3E';

export default function CarImage({
  src,
  imageUrl,
  images,
  alt = 'Car image',
  height = 'auto',
  width = '100%',
  objectFit = 'cover',
  aspectRatio,
  borderRadius,
  sx,
  className,
}: CarImageProps) {
  const theme = useTheme();
  const [hasError, setHasError] = useState(false);

  const fallbackSrc = src || imageUrl || DEFAULT_PLACEHOLDER;
  const desktopSrc = images?.desktop;
  const tabletSrc = images?.tablet;
  const mobileSrc = images?.mobile;

  const defaultImgSrc = mobileSrc || tabletSrc || desktopSrc || fallbackSrc;

  const mdBreakpoint = theme.breakpoints.values.md;
  const smBreakpoint = theme.breakpoints.values.sm;

  if (hasError) {
    return (
      <Box
        component="img"
        src={DEFAULT_PLACEHOLDER}
        alt={alt}
        className={className}
        sx={{
          width,
          height,
          objectFit,
          aspectRatio,
          borderRadius,
          display: 'block',
          ...sx,
        }}
      />
    );
  }

  return (
    <Box
      component="picture"
      className={className}
      sx={{
        display: 'block',
        width,
        height,
        overflow: 'hidden',
        borderRadius,
        ...sx,
      }}
    >
      {desktopSrc && (
        <source
          media={`(min-width: ${mdBreakpoint}px)`}
          srcSet={desktopSrc}
        />
      )}
      {tabletSrc && (
        <source
          media={`(min-width: ${smBreakpoint}px)`}
          srcSet={tabletSrc}
        />
      )}
      {mobileSrc && (
        <source
          media={`(max-width: ${smBreakpoint - 0.05}px)`}
          srcSet={mobileSrc}
        />
      )}
      <Box
        component="img"
        src={defaultImgSrc}
        alt={alt}
        onError={() => setHasError(true)}
        sx={{
          width: '100%',
          height: '100%',
          objectFit,
          aspectRatio,
          borderRadius,
          display: 'block',
        }}
      />
    </Box>
  );
}

