import React from 'react';
import { useQuery } from '@apollo/client';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  IconButton,
  Typography,
  Box,
  Grid,
  CircularProgress,
  Alert,
  Divider,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import { GET_CAR } from '../types/car';
import type { GetCarData, GetCarVars } from '../types/car';
import CarImage from './CarImage';

export interface CarDetailsModalProps {
  carId: string | null;
  open: boolean;
  onClose: () => void;
}

export default function CarDetailsModal({
  carId,
  open,
  onClose,
}: CarDetailsModalProps) {
  const { data, loading, error } = useQuery<GetCarData, GetCarVars>(GET_CAR, {
    variables: { id: carId || '' },
    skip: !carId || !open,
    fetchPolicy: 'cache-and-network',
  });

  const car = data?.car;

  return (
