import React, { useState } from 'react';
import {
  Box,
  Grid,
  CircularProgress,
  Alert,
  Typography,
  Button,
  Stack,
} from '@mui/material';
import { Car } from '../types/car';
import useCars from '../hooks/useCars';
import useCarFilters from '../hooks/useCarFilters';
import CarCard from './CarCard';
import CarFilters from './CarFilters';
import CarDetailsModal from './CarDetailsModal';

export interface CarListProps {
  onCarSelect?: (car: Car) => void;
}

export default function CarList({ onCarSelect }: CarListProps) {
  const { cars, loading, error, refetch } = useCars();
  const [selectedCarId, setSelectedCarId] = useState<string | null>(null);
  const [modalOpen, setModalOpen] = useState(false);

  const {
    modelSearch,
    setModelSearch,
    yearFilter,
    setYearFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    sortOption,
    setSortOption,
    filteredCars,
    availableYears,
    resetFilters,
  } = useCarFilters(cars);

  const handleCarClick = (car: Car) => {
    setSelectedCarId(car.id);
    setModalOpen(true);
    onCarSelect?.(car);
  };

  const handleCloseModal = () => {
    setModalOpen(false);
    setSelectedCarId(null);
  };

  return (
    <Box sx={{ width: '100%', py: 2 }}>
      <CarFilters
        modelSearch={modelSearch}
        setModelSearch={setModelSearch}
        yearFilter={yearFilter}
        setYearFilter={setYearFilter}
        availableYears={availableYears}
        sortBy={sortBy}
        setSortBy={setSortBy}
        sortOrder={sortOrder}
        setSortOrder={setSortOrder}
        sortOption={sortOption}
        setSortOption={setSortOption}
        resetFilters={resetFilters}
      />

      {loading && (
        <Box
          display="flex"
          justifyContent="center"
          alignItems="center"
          minHeight="300px"
        >
          <CircularProgress />
        </Box>
      )}

      {error && !loading && (
        <Alert
          severity="error"
          sx={{ my: 3 }}
          action={
            <Button color="inherit" size="small" onClick={() => refetch()}>
              Retry
            </Button>
          }
        >
          {error.message || 'Failed to load cars. Please try again.'}
        </Alert>
      )}

      {!loading && !error && filteredCars.length === 0 && (
        <Box
          sx={{
            textAlign: 'center',
            py: 8,
            px: 2,
            backgroundColor: 'background.paper',
            borderRadius: 2,
            border: '1px dashed',
            borderColor: 'divider',
          }}
        >
          <Typography variant="h6" color="text.secondary" gutterBottom>
            No cars found
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {cars.length === 0
              ? 'There are currently no cars in the inventory.'
              : 'No cars match your search and filter criteria. Try adjusting your filters.'}
          </Typography>
          {cars.length > 0 && (
            <Button variant="outlined" color="primary" onClick={resetFilters}>
              Reset Filters
            </Button>
          )}
        </Box>
      )}

      {!loading && !error && filteredCars.length > 0 && (
        <>
          <Box sx={{ mb: 2 }}>
            <Typography variant="body2" color="text.secondary">
              Showing {filteredCars.length} {filteredCars.length === 1 ? 'car' : 'cars'}
            </Typography>
          </Box>
          <Grid container spacing={3}>
            {filteredCars.map((car) => (
              <Grid item key={car.id} xs={12} sm={6} md={4} lg={4}>
                <CarCard car={car} onClick={() => handleCarClick(car)} />
              </Grid>
            ))}
          </Grid>
        </>
      )}

      <CarDetailsModal
        carId={selectedCarId}
        open={modalOpen}
        onClose={handleCloseModal}
      />
    </Box>
  );
}

