import { describe, it, expect } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useCarFilters } from '../useCarFilters';
import { Car } from '../../types/car';

const mockCars: Car[] = [
  {
    id: '1',
    make: 'Toyota',
    model: 'Camry',
    year: 2020,
    price: 24000,
    mileage: 30000,
    createdAt: '2023-01-01T00:00:00.000Z',
  },
  {
    id: '2',
    make: 'Honda',
    model: 'Civic',
    year: 2022,
    price: 22000,
    mileage: 15000,
    createdAt: '2023-02-01T00:00:00.000Z',
  },
  {
    id: '3',
    make: 'Ford',
    model: 'Mustang',
    year: 2019,
    price: 35000,
    mileage: 45000,
    createdAt: '2022-12-01T00:00:00.000Z',
  },
  {
    id: '4',
    make: 'Toyota',
    model: 'Corolla',
    year: 2020,
    price: 19000,
    mileage: 40000,
    createdAt: '2023-03-01T00:00:00.000Z',
  },
];

describe('useCarFilters hook', () => {
  describe('Initial state and defaults', () => {
    it('returns default state when initialized without options', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      expect(result.current.modelSearch).toBe('');
      expect(result.current.search).toBe('');
      expect(result.current.searchTerm).toBe('');
      expect(result.current.yearFilter).toBe('');
      expect(result.current.selectedYear).toBe('');
      expect(result.current.sortBy).toBe('');
      expect(result.current.sortOrder).toBe('asc');
      expect(result.current.sortOption).toBe('');
      expect(result.current.filteredCars).toHaveLength(4);
    });

    it('initializes with provided options', () => {
      const { result } = renderHook(() =>
        useCarFilters(mockCars, {
          initialSearch: 'Civic',
          initialYear: 2022,
          initialSortBy: 'price',
          initialSortOrder: 'desc',
        })
      );

      expect(result.current.modelSearch).toBe('Civic');
      expect(result.current.yearFilter).toBe(2022);
      expect(result.current.sortBy).toBe('price');
      expect(result.current.sortOrder).toBe('desc');
      expect(result.current.sortOption).toBe('price_desc');
      expect(result.current.filteredCars).toHaveLength(1);
      expect(result.current.filteredCars[0]?.model).toBe('Civic');
    });

    it('handles undefined or empty car list gracefully', () => {
      const { result } = renderHook(() => useCarFilters());
      expect(result.current.filteredCars).toEqual([]);
      expect(result.current.availableYears).toEqual([]);
    });
  });

  describe('availableYears', () => {
    it('extracts unique years in descending order', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));
      expect(result.current.availableYears).toEqual([2022, 2020, 2019]);
    });

    it('filters out invalid or non-numeric years', () => {
      const carsWithInvalidYears = [
        { id: '1', make: 'Car', model: 'A', year: 2021 },
        { id: '2', make: 'Car', model: 'B', year: NaN },
        { id: '3', make: 'Car', model: 'C', year: (undefined as unknown) as number },
      ] as unknown as Car[];

      const { result } = renderHook(() => useCarFilters(carsWithInvalidYears));
      expect(result.current.availableYears).toEqual([2021]);
    });
  });

  describe('Search filtering', () => {
    it('filters by model name (case-insensitive)', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setModelSearch('civic');
      });

      expect(result.current.filteredCars).toHaveLength(1);
      expect(result.current.filteredCars[0]?.model).toBe('Civic');
    });

    it('filters by make name (case-insensitive)', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSearch('toyota');
      });

      expect(result.current.filteredCars).toHaveLength(2);
      expect(result.current.filteredCars.map((c) => c.model)).toEqual(['Camry', 'Corolla']);
    });

    it('filters by combined make and model search query', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSearchTerm('Toyota Camry');
      });

      expect(result.current.filteredCars).toHaveLength(1);
      expect(result.current.filteredCars[0]?.id).toBe('1');
    });

    it('trims whitespace in search queries', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setModelSearch('   Mustang   ');
      });

      expect(result.current.filteredCars).toHaveLength(1);
      expect(result.current.filteredCars[0]?.model).toBe('Mustang');
    });

    it('returns all cars when search query is only whitespace', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setModelSearch('   ');
      });

      expect(result.current.filteredCars).toHaveLength(4);
    });
  });

  describe('Year filtering', () => {
    it('filters by numeric year', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setYearFilter(2020);
      });

      expect(result.current.filteredCars).toHaveLength(2);
      expect(result.current.filteredCars.every((c) => c.year === 2020)).toBe(true);
    });

    it('filters by string year', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSelectedYear('2019');
      });

      expect(result.current.filteredCars).toHaveLength(1);
      expect(result.current.filteredCars[0]?.model).toBe('Mustang');
    });

    it('ignores year filter when set to empty string or "all"', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setYearFilter('all');
      });
      expect(result.current.filteredCars).toHaveLength(4);

      act(() => {
        result.current.setYearFilter('ALL');
      });
      expect(result.current.filteredCars).toHaveLength(4);

      act(() => {
        result.current.setYearFilter('');
      });
      expect(result.current.filteredCars).toHaveLength(4);
    });
  });

  describe('Sorting', () => {
    it('sorts by price ascending and descending', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortBy('price');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.price)).toEqual([19000, 22000, 24000, 35000]);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.price)).toEqual([35000, 24000, 22000, 19000]);
    });

    it('sorts by year ascending and descending', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortBy('year');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.year)).toEqual([2019, 2020, 2020, 2022]);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.year)).toEqual([2022, 2020, 2020, 2019]);
    });

    it('sorts by mileage ascending and descending', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortBy('mileage');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.mileage)).toEqual([15000, 30000, 40000, 45000]);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.mileage)).toEqual([45000, 40000, 30000, 15000]);
    });

    it('sorts by make alphabetically', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortBy('make');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.make)).toEqual(['Ford', 'Honda', 'Toyota', 'Toyota']);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.make)).toEqual(['Toyota', 'Toyota', 'Honda', 'Ford']);
    });

    it('sorts by model alphabetically', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortBy('model');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.model)).toEqual(['Camry', 'Civic', 'Corolla', 'Mustang']);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.model)).toEqual(['Mustang', 'Corolla', 'Civic', 'Camry']);
    });

    it('sorts by createdAt date', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortBy('createdAt');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.id)).toEqual(['3', '1', '2', '4']);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.id)).toEqual(['4', '2', '1', '3']);
    });

    it('handles cars with missing or undefined sort field values', () => {
      const carsWithMissingFields = [
        { id: '1', make: undefined, model: undefined, price: undefined, mileage: undefined, year: undefined },
        { id: '2', make: 'Audi', model: 'A4', price: 20000, mileage: 10000, year: 2021 },
      ] as unknown as Car[];

      const { result } = renderHook(() => useCarFilters(carsWithMissingFields));

      act(() => {
        result.current.setSortBy('price');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars[0]?.id).toBe('1');
      expect(result.current.filteredCars[1]?.id).toBe('2');

      act(() => {
        result.current.setSortBy('make');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars[0]?.id).toBe('1');
      expect(result.current.filteredCars[1]?.id).toBe('2');
    });
  });

  describe('setSortOption and sortOption string handling', () => {
    it('parses combined sort option string with underscore delimiter', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortOption('price_desc');
      });

      expect(result.current.sortBy).toBe('price');
      expect(result.current.sortOrder).toBe('desc');
      expect(result.current.sortOption).toBe('price_desc');
    });

    it('parses combined sort option string with hyphen delimiter', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortOption('mileage-asc');
      });

      expect(result.current.sortBy).toBe('mileage');
      expect(result.current.sortOrder).toBe('asc');
      expect(result.current.sortOption).toBe('mileage_asc');
    });

    it('defaults to asc order when no order is specified in option string', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setSortOption('year');
      });

      expect(result.current.sortBy).toBe('year');
      expect(result.current.sortOrder).toBe('asc');
      expect(result.current.sortOption).toBe('year_asc');
    });

    it('resets sort state when option is empty or "none"', () => {
      const { result } = renderHook(() =>
        useCarFilters(mockCars, { initialSortBy: 'price', initialSortOrder: 'desc' })
      );

      act(() => {
        result.current.setSortOption('none');
      });

      expect(result.current.sortBy).toBe('');
      expect(result.current.sortOrder).toBe('asc');
      expect(result.current.sortOption).toBe('');

      act(() => {
        result.current.setSortOption('price_desc');
      });
      expect(result.current.sortBy).toBe('price');

      act(() => {
        result.current.setSortOption('');
      });
      expect(result.current.sortBy).toBe('');
      expect(result.current.sortOption).toBe('');
    });
  });

  describe('resetFilters', () => {
    it('resets all filter and sort values back to initial defaults', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setModelSearch('Civic');
        result.current.setYearFilter(2022);
        result.current.setSortBy('price');
        result.current.setSortOrder('desc');
      });

      expect(result.current.modelSearch).toBe('Civic');
      expect(result.current.yearFilter).toBe(2022);
      expect(result.current.sortBy).toBe('price');
      expect(result.current.sortOrder).toBe('desc');

      act(() => {
        result.current.resetFilters();
      });

      expect(result.current.modelSearch).toBe('');
      expect(result.current.yearFilter).toBe('');
      expect(result.current.sortBy).toBe('');
      expect(result.current.sortOrder).toBe('asc');
      expect(result.current.filteredCars).toHaveLength(4);
    });

    it('resets to custom initial options if provided', () => {
      const initialOptions = {
        initialSearch: 'Toyota',
        initialYear: 2020,
        initialSortBy: 'price' as const,
        initialSortOrder: 'asc' as const,
      };

      const { result } = renderHook(() => useCarFilters(mockCars, initialOptions));

      act(() => {
        result.current.setModelSearch('Ford');
        result.current.setYearFilter(2019);
        result.current.setSortBy('mileage');
        result.current.setSortOrder('desc');
      });

      act(() => {
        result.current.resetFilters();
      });

      expect(result.current.modelSearch).toBe('Toyota');
      expect(result.current.yearFilter).toBe(2020);
      expect(result.current.sortBy).toBe('price');
      expect(result.current.sortOrder).toBe('asc');
      expect(result.current.filteredCars).toHaveLength(2);
    });
  });

  describe('Combined search, filter, and sort interactions', () => {
    it('applies search, year filter, and sorting simultaneously', () => {
      const { result } = renderHook(() => useCarFilters(mockCars));

      act(() => {
        result.current.setModelSearch('Toyota');
        result.current.setYearFilter(2020);
        result.current.setSortOption('price_desc');
      });

      expect(result.current.filteredCars).toHaveLength(2);
      expect(result.current.filteredCars[0]?.model).toBe('Camry'); // $24,000
      expect(result.current.filteredCars[1]?.model).toBe('Corolla'); // $19,000
    });
  });
