      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortBy('price');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.price)).toEqual([18000, 22000, 24000, 35000]);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.price)).toEqual([35000, 24000, 22000, 18000]);
    });

    it('sorts cars by year asc and desc', () => {
      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortBy('year');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.year)).toEqual([2018, 2020, 2020, 2022]);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.year)).toEqual([2022, 2020, 2020, 2018]);
    });

    it('sorts cars by mileage asc and desc', () => {
      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortBy('mileage');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.mileage)).toEqual([5000, 15000, 30000, 45000]);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.mileage)).toEqual([45000, 30000, 15000, 5000]);
    });

    it('sorts cars by make asc and desc', () => {
      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortBy('make');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.make)).toEqual(['Ford', 'Honda', 'Honda', 'Toyota']);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.make)).toEqual(['Toyota', 'Honda', 'Honda', 'Ford']);
    });

    it('sorts cars by model asc and desc', () => {
      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortBy('model');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.model)).toEqual(['Accord', 'Camry', 'Civic', 'Mustang']);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.model)).toEqual(['Mustang', 'Civic', 'Camry', 'Accord']);
    });

    it('sorts cars by createdAt asc and desc', () => {
      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortBy('createdAt');
        result.current.setSortOrder('asc');
      });
      expect(result.current.filteredCars.map((c) => c.id)).toEqual(['1', '4', '2', '3']);

      act(() => {
        result.current.setSortOrder('desc');
      });
      expect(result.current.filteredCars.map((c) => c.id)).toEqual(['3', '2', '4', '1']);
    });
  });

  describe('setSortOption & resetFilters', () => {
    it('parses composite sort option strings with underscore separator', () => {
      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortOption('price_desc');
      });
      expect(result.current.sortBy).toBe('price');
      expect(result.current.sortOrder).toBe('desc');
      expect(result.current.sortOption).toBe('price_desc');
    });

    it('parses composite sort option strings with hyphen separator', () => {
      const { result } = renderHook(() => useCarFilters(sampleCars));

      act(() => {
        result.current.setSortOption('year-asc');
      });
      expect(result.current.sortBy).toBe('year');
      expect(result.current.sortOrder).toBe('asc');
    });

    it('clears sorting when given empty or "none"', () => {
      const { result } = renderHook(() =>
        useCarFilters(sampleCars, { initialSortBy: 'price', initialSortOrder: 'desc' })
      );

      act(() => {
        result.current.setSortOption('none');
      });
      expect(result.current.sortBy).toBe('');
      expect(result.current.sortOrder).toBe('asc');

      act(() => {
        result.current.setSortOption('');
      });
      expect(result.current.sortBy).toBe('');
      expect(result.current.sortOrder).toBe('asc');
    });

    it('resets all filters back to initial values', () => {
      const { result } = renderHook(() =>
        useCarFilters(sampleCars, {
          initialSearch: 'Ford',
          initialYear: 2022,
          initialSortBy: 'price',
          initialSortOrder: 'desc',
        })
      );

      act(() => {
        result.current.setModelSearch('Toyota');
        result.current.setYearFilter(2020);
        result.current.setSortBy('mileage');
        result.current.setSortOrder('asc');
      });

      expect(result.current.modelSearch).toBe('Toyota');
      expect(result.current.yearFilter).toBe(2020);

      act(() => {
        result.current.resetFilters();
      });

      expect(result.current.modelSearch).toBe('Ford');
      expect(result.current.yearFilter).toBe(2022);
      expect(result.current.sortBy).toBe('price');
      expect(result.current.sortOrder).toBe('desc');
    });
  });
});

describe('CarFilters Component', () => {
  const defaultProps: CarFiltersProps = {
    modelSearch: '',
    availableYears: [2022, 2021, 2020],
    sortBy: '',
    sortOrder: 'asc',
  };

  it('renders search input, year select, sort select, and reset button', () => {
    render(<CarFilters {...defaultProps} />);

    expect(screen.getByLabelText(/Search Make or Model/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/Year/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/Sort By/i)).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Reset/i })).toBeInTheDocument();
  });

  it('triggers search callbacks on typing in the search input', () => {
    const onModelSearchChange = vi.fn();
    const onSearchChange = vi.fn();
    const setModelSearch = vi.fn();

    render(
      <CarFilters
        {...defaultProps}
        onModelSearchChange={onModelSearchChange}
        onSearchChange={onSearchChange}
        setModelSearch={setModelSearch}
      />
    );

    const input = screen.getByLabelText(/Search Make or Model/i);
    fireEvent.change(input, { target: { value: 'Camry' } });

    expect(onModelSearchChange).toHaveBeenCalledWith('Camry');
    expect(onSearchChange).toHaveBeenCalledWith('Camry');
    expect(setModelSearch).toHaveBeenCalledWith('Camry');
  });

  it('triggers year change callbacks when year is selected', () => {
    const onYearChange = vi.fn();
    const setYearFilter = vi.fn();

    render(
      <CarFilters
        {...defaultProps}
        availableYears={[2022, 2020]}
        onYearChange={onYearChange}
        setYearFilter={setYearFilter}
      />
    );

    const yearSelect = screen.getByLabelText(/Year/i);
    fireEvent.mouseDown(yearSelect);

    const option2022 = screen.getByRole('option', { name: '2022' });
    fireEvent.click(option2022);

    expect(onYearChange).toHaveBeenCalledWith(2022);
    expect(setYearFilter).toHaveBeenCalledWith(2022);
  });

  it('triggers sort change callbacks when sort option is selected', () => {
    const onSortChange = vi.fn();
    const setSortBy = vi.fn();
    const setSortOrder = vi.fn();
    const setSortOption = vi.fn();

    render(
      <CarFilters
        {...defaultProps}
        onSortChange={onSortChange}
        setSortBy={setSortBy}
        setSortOrder={setSortOrder}
        setSortOption={setSortOption}
      />
    );

    const sortSelect = screen.getByLabelText(/Sort By/i);
    fireEvent.mouseDown(sortSelect);

    const priceLowOption = screen.getByRole('option', { name: /Price: Low to High/i });
    fireEvent.click(priceLowOption);

    expect(setSortOption).toHaveBeenCalledWith('price_asc');
    expect(setSortBy).toHaveBeenCalledWith('price');
    expect(setSortOrder).toHaveBeenCalledWith('asc');
    expect(onSortChange).toHaveBeenCalledWith('price', 'asc');
  });

  it('handles default sort selection resetting sortBy and sortOrder', () => {
    const onSortChange = vi.fn();
    const setSortBy = vi.fn();
    const setSortOrder = vi.fn();

    render(
      <CarFilters
        {...defaultProps}
        sortBy="price"
        sortOrder="desc"
        onSortChange={onSortChange}
        setSortBy={setSortBy}
        setSortOrder={setSortOrder}
      />
    );

    const sortSelect = screen.getByLabelText(/Sort By/i);
    fireEvent.mouseDown(sortSelect);

    const defaultOption = screen.getByRole('option', { name: /Default/i });
    fireEvent.click(defaultOption);

    expect(setSortBy).toHaveBeenCalledWith('');
    expect(setSortOrder).toHaveBeenCalledWith('asc');
    expect(onSortChange).toHaveBeenCalledWith('', 'asc');
  });

  it('triggers reset callbacks when reset button is clicked', () => {
    const resetFilters = vi.fn();
    const onReset = vi.fn();

    render(
      <CarFilters
        {...defaultProps}
        resetFilters={resetFilters}
        onReset={onReset}
      />
    );

    const resetButton = screen.getByRole('button', { name: /Reset/i });
    fireEvent.click(resetButton);

    expect(resetFilters).toHaveBeenCalledTimes(1);
    expect(onReset).toHaveBeenCalledTimes(1);
  });

  it('integrates properly with useCarFilters hook return values', () => {
    function FilterIntegrationTest() {
      const filters = useCarFilters(sampleCars);

      return (
        <div>
          <CarFilters
            modelSearch={filters.modelSearch}
            onModelSearchChange={filters.setModelSearch}
            yearFilter={filters.yearFilter}
            onYearChange={filters.setYearFilter}
            availableYears={filters.availableYears}
            sortBy={filters.sortBy}
            sortOrder={filters.sortOrder}
            onSortChange={(field, order) => {
              filters.setSortBy(field);
              filters.setSortOrder(order);
            }}
            resetFilters={filters.resetFilters}
          />
          <div data-testid="car-count">{filters.filteredCars.length}</div>
          <div data-testid="first-car">{filters.filteredCars[0]?.model}</div>
        </div>
      );
    }

    render(<FilterIntegrationTest />);

    expect(screen.getByTestId('car-count')).toHaveTextContent('4');

    const searchInput = screen.getByLabelText(/Search Make or Model/i);
    fireEvent.change(searchInput, { target: { value: 'Mustang' } });

    expect(screen.getByTestId('car-count')).toHaveTextContent('1');
    expect(screen.getByTestId('first-car')).toHaveTextContent('Mustang');

    const resetButton = screen.getByRole('button', { name: /Reset/i });
    fireEvent.click(resetButton);

    expect(screen.getByTestId('car-count')).toHaveTextContent('4');
  });
});

