import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import CarCard from '../CarCard';
import CarList from '../CarList';
import { Car } from '../../types/car';
import useCars from '../../hooks/useCars';

vi.mock('../../hooks/useCars');
const mockUseCars = vi.mocked(useCars);

vi.mock('../CarDetailsModal', () => {
  return {
    default: function MockCarDetailsModal({
      open,
      carId,
      onClose,
    }: {
      open: boolean;
      carId: string | null;
      onClose: () => void;
    }) {
      if (!open) return null;
      return (
        <div data-testid="car-details-modal">
          <span>Selected Car ID: {carId}</span>
          <button onClick={onClose}>Close Modal</button>
        </div>
      );
    },
  };
});

const mockCars: Car[] = [
  {
    id: '1',
    make: 'Toyota',
    model: 'Camry',
    year: 2022,
    price: 26500,
    mileage: 15420,
    color: 'Blue',
    vin: '4T1B11HK5JU123456',
    description: 'Well-maintained sedan with excellent fuel economy.',
    imageUrl: 'https://example.com/camry.jpg',
  },
  {
    id: '2',
    make: 'Honda',
    model: 'Civic',
    year: 2021,
    price: 22000,
    mileage: 28000,
    color: 'Red',
    vin: '19XFC2F59ME654321',
    description: 'Sporty compact car with tech package.',
    imageUrl: 'https://example.com/civic.jpg',
  },
  {
    id: '3',
    make: 'Tesla',
    model: 'Model 3',
    year: 2023,
    price: 38990,
    mileage: 5000,
    color: 'White',
    vin: '5YJ3E1EB7PF987654',
    description: 'All-electric sedan with autopilot.',
    imageUrl: 'https://example.com/model3.jpg',
  },
];

describe('CarCard', () => {
  const singleCar: Car = mockCars[0]!;

  it('renders car details including title, formatted price, mileage, color, and VIN', () => {
    render(<CarCard car={singleCar} />);

    expect(screen.getByText('2022 Toyota Camry')).toBeInTheDocument();
    expect(screen.getByText('$26,500')).toBeInTheDocument();
    expect(screen.getByText('15,420 mi')).toBeInTheDocument();
    expect(screen.getByText('Blue')).toBeInTheDocument();
    expect(screen.getByText('VIN: 123456')).toBeInTheDocument();
    expect(
      screen.getByText('Well-maintained sedan with excellent fuel economy.')
    ).toBeInTheDocument();
  });

  it('handles optional car properties gracefully when missing', () => {
    const minimalCar: Car = {
      id: '99',
      make: 'Ford',
      model: 'Mustang',
      year: 2020,
      price: 32000,
    };

    render(<CarCard car={minimalCar} />);

    expect(screen.getByText('2020 Ford Mustang')).toBeInTheDocument();
    expect(screen.getByText('$32,000')).toBeInTheDocument();
    expect(screen.queryByText(/mi$/)).not.toBeInTheDocument();
    expect(screen.queryByText(/^VIN:/)).not.toBeInTheDocument();
  });

  it('triggers onClick handler when card is clicked', async () => {
    const handleClick = vi.fn();
    render(<CarCard car={singleCar} onClick={handleClick} />);

    const cardButton = screen.getByRole('button');
    await userEvent.click(cardButton);

    expect(handleClick).toHaveBeenCalledTimes(1);
  });

  it('renders without action area when onClick is not provided', () => {
    render(<CarCard car={singleCar} />);
    expect(screen.queryByRole('button')).not.toBeInTheDocument();
  });
});

describe('CarList', () => {
  const mockRefetch = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('renders loading spinner when loading is true', () => {
    mockUseCars.mockReturnValue({
      cars: [],
      loading: true,
      error: null,
      refetch: mockRefetch,
    });

    render(<CarList />);

    expect(screen.getByRole('progressbar')).toBeInTheDocument();
    expect(screen.queryByText(/Showing/)).not.toBeInTheDocument();
  });

  it('renders error alert with retry button when query fails', async () => {
    const errorMessage = 'Network error: Failed to fetch';
    mockUseCars.mockReturnValue({
      cars: [],
      loading: false,
      error: new Error(errorMessage),
      refetch: mockRefetch,
    });

    render(<CarList />);

    expect(screen.getByText(errorMessage)).toBeInTheDocument();
    const retryButton = screen.getByRole('button', { name: /retry/i });
    expect(retryButton).toBeInTheDocument();

    await userEvent.click(retryButton);
    expect(mockRefetch).toHaveBeenCalledTimes(1);
  });

  it('renders empty inventory message when there are no cars', () => {
    mockUseCars.mockReturnValue({
      cars: [],
      loading: false,
      error: null,
      refetch: mockRefetch,
    });

    render(<CarList />);

    expect(screen.getByText('No cars found')).toBeInTheDocument();
    expect(
      screen.getByText('There are currently no cars in the inventory.')
    ).toBeInTheDocument();
  });

  it('renders list of cars and car count correctly', () => {
    mockUseCars.mockReturnValue({
      cars: mockCars,
      loading: false,
      error: null,
      refetch: mockRefetch,
    });

    render(<CarList />);

    expect(screen.getByText('Showing 3 cars')).toBeInTheDocument();
    expect(screen.getByText('2022 Toyota Camry')).toBeInTheDocument();
    expect(screen.getByText('2021 Honda Civic')).toBeInTheDocument();
    expect(screen.getByText('2023 Tesla Model 3')).toBeInTheDocument();
  });

  it('filters cars by search text and allows resetting filters', async () => {
    mockUseCars.mockReturnValue({
      cars: mockCars,
      loading: false,
      error: null,
      refetch: mockRefetch,
    });

    render(<CarList />);

    const searchInput = screen.getByPlaceholderText(/search/i);
    await userEvent.type(searchInput, 'Tesla');

    expect(screen.getByText('Showing 1 car')).toBeInTheDocument();
    expect(screen.getByText('2023 Tesla Model 3')).toBeInTheDocument();
    expect(screen.queryByText('2022 Toyota Camry')).not.toBeInTheDocument();

    await userEvent.clear(searchInput);
    await userEvent.type(searchInput, 'NonexistentModel');

    expect(screen.getByText('No cars found')).toBeInTheDocument();
    expect(
      screen.getByText(
        'No cars match your search and filter criteria. Try adjusting your filters.'
      )
    ).toBeInTheDocument();

    const resetButton = screen.getByRole('button', { name: /reset filters/i });
    await userEvent.click(resetButton);

    expect(screen.getByText('Showing 3 cars')).toBeInTheDocument();
    expect(screen.getByText('2022 Toyota Camry')).toBeInTheDocument();
  });

  it('opens CarDetailsModal and invokes onCarSelect callback on card click', async () => {
    const handleCarSelect = vi.fn();
    mockUseCars.mockReturnValue({
      cars: mockCars,
      loading: false,
      error: null,
      refetch: mockRefetch,
    });

    render(<CarList onCarSelect={handleCarSelect} />);

    const firstCard = screen.getByText('2022 Toyota Camry').closest('button');
    expect(firstCard).toBeInTheDocument();
    if (firstCard) {
      await userEvent.click(firstCard);
    }

    expect(handleCarSelect).toHaveBeenCalledWith(mockCars[0]);
    expect(screen.getByTestId('car-details-modal')).toBeInTheDocument();
    expect(screen.getByText('Selected Car ID: 1')).toBeInTheDocument();

    const closeModalBtn = screen.getByRole('button', { name: /close modal/i });
    await userEvent.click(closeModalBtn);

    expect(screen.queryByTestId('car-details-modal')).not.toBeInTheDocument();
  });
});

