import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, beforeEach, vi } from 'vitest';
import AddCarForm from '../AddCarForm';
import useCars from '../../hooks/useCars';

vi.mock('../../hooks/useCars');

const mockUseCars = vi.mocked(useCars);

describe('AddCarForm', () => {
  const mockAddCar = vi.fn();
  const defaultHookReturn = {
    cars: [],
    loading: false,
    error: undefined,
    refetch: vi.fn(),
    addCar: mockAddCar,
    addingCar: false,
    addCarError: undefined,
    updateCar: vi.fn(),
    updatingCar: false,
    updateCarError: undefined,
    deleteCar: vi.fn(),
    deletingCar: false,
    deleteCarError: undefined,
  };

  beforeEach(() => {
    vi.clearAllMocks();
    mockUseCars.mockReturnValue(defaultHookReturn as any);
  });

  it('renders the form with default values and all inputs', () => {
    render(<AddCarForm />);

    expect(screen.getByLabelText(/make/i)).toHaveValue('');
    expect(screen.getByLabelText(/model/i)).toHaveValue('');
    expect(screen.getByLabelText(/year/i)).toHaveValue(new Date().getFullYear());
    expect(screen.getByLabelText(/price/i)).toHaveValue(null);
    expect(screen.getByLabelText(/color/i)).toHaveValue('');
    expect(screen.getByLabelText(/mileage/i)).toHaveValue(null);
    expect(screen.getByLabelText(/status/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/description/i)).toHaveValue('');
    expect(screen.getByRole('button', { name: /add car/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /reset/i })).toBeInTheDocument();
  });

  it('renders "Cancel" button when onCancel prop is provided', () => {
    const onCancel = vi.fn();
    render(<AddCarForm onCancel={onCancel} />);

    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();
  });

  it('updates form fields as user types', async () => {
    const user = userEvent.setup();
    render(<AddCarForm />);

    const makeInput = screen.getByLabelText(/make/i);
    const modelInput = screen.getByLabelText(/model/i);
    const priceInput = screen.getByLabelText(/price/i);
    const colorInput = screen.getByLabelText(/color/i);
    const mileageInput = screen.getByLabelText(/mileage/i);
    const descInput = screen.getByLabelText(/description/i);

    await user.type(makeInput, 'Toyota');
    await user.type(modelInput, 'Corolla');
    await user.type(priceInput, '20000');
    await user.type(colorInput, 'Blue');
    await user.type(mileageInput, '15000');
    await user.type(descInput, 'Great condition');

    expect(makeInput).toHaveValue('Toyota');
    expect(modelInput).toHaveValue('Corolla');
    expect(priceInput).toHaveValue(20000);
    expect(colorInput).toHaveValue('Blue');
    expect(mileageInput).toHaveValue(15000);
    expect(descInput).toHaveValue('Great condition');
  });

  it('validates required fields on submission', async () => {
    const user = userEvent.setup();
    render(<AddCarForm />);

    const submitButton = screen.getByRole('button', { name: /add car/i });
    await user.click(submitButton);

    expect(mockAddCar).not.toHaveBeenCalled();
    expect(screen.getByText('Make is required')).toBeInTheDocument();
    expect(screen.getByText('Model is required')).toBeInTheDocument();
    expect(screen.getByText('Price is required')).toBeInTheDocument();
  });

  it('validates invalid year and negative price or mileage values', async () => {
    const user = userEvent.setup();
    render(<AddCarForm />);

    const yearInput = screen.getByLabelText(/year/i);
    const priceInput = screen.getByLabelText(/price/i);
    const mileageInput = screen.getByLabelText(/mileage/i);

    await user.clear(yearInput);
    await user.type(yearInput, '1800');
    await user.type(priceInput, '-100');
    await user.type(mileageInput, '-50');

    await user.click(screen.getByRole('button', { name: /add car/i }));

    const maxYear = new Date().getFullYear() + 1;
    expect(
      screen.getByText(`Enter a valid year between 1886 and ${maxYear}`)
    ).toBeInTheDocument();
    expect(screen.getByText('Price must be a non-negative number')).toBeInTheDocument();
    expect(screen.getByText('Mileage must be a non-negative number')).toBeInTheDocument();
    expect(mockAddCar).not.toHaveBeenCalled();
  });

  it('clears field validation errors when user types in the field', async () => {
    const user = userEvent.setup();
    render(<AddCarForm />);

    await user.click(screen.getByRole('button', { name: /add car/i }));
    expect(screen.getByText('Make is required')).toBeInTheDocument();

    const makeInput = screen.getByLabelText(/make/i);
    await user.type(makeInput, 'Honda');

    expect(screen.queryByText('Make is required')).not.toBeInTheDocument();
  });

  it('submits form with valid data and calls onSuccess callback', async () => {
    const user = userEvent.setup();
    const onSuccess = vi.fn();
    mockAddCar.mockResolvedValueOnce({ id: '1', make: 'Honda', model: 'Civic' });

    render(<AddCarForm onSuccess={onSuccess} />);

    await user.type(screen.getByLabelText(/make/i), 'Honda');
    await user.type(screen.getByLabelText(/model/i), 'Civic');
    await user.type(screen.getByLabelText(/price/i), '25000');
    await user.type(screen.getByLabelText(/color/i), 'Red');
    await user.type(screen.getByLabelText(/mileage/i), '12000');
    await user.type(screen.getByLabelText(/description/i), 'Reliable commuter');

    await user.click(screen.getByRole('button', { name: /add car/i }));

    await waitFor(() => {
      expect(mockAddCar).toHaveBeenCalledTimes(1);
      expect(mockAddCar).toHaveBeenCalledWith({
        make: 'Honda',
        model: 'Civic',
        year: new Date().getFullYear(),
        price: 25000,
        color: 'Red',
        mileage: 12000,
        status: 'AVAILABLE',
        description: 'Reliable commuter',
      });
    });

    expect(await screen.findByText('Car added successfully!')).toBeInTheDocument();
    expect(onSuccess).toHaveBeenCalledTimes(1);
    expect(screen.getByLabelText(/make/i)).toHaveValue('');
    expect(screen.getByLabelText(/model/i)).toHaveValue('');
  });

  it('submits correctly with only required fields and empty optional fields', async () => {
    const user = userEvent.setup();
    mockAddCar.mockResolvedValueOnce({ id: '2', make: 'Ford', model: 'Focus' });

    render(<AddCarForm />);

    await user.type(screen.getByLabelText(/make/i), 'Ford');
    await user.type(screen.getByLabelText(/model/i), 'Focus');
    await user.type(screen.getByLabelText(/price/i), '18000');

    await user.click(screen.getByRole('button', { name: /add car/i }));

    await waitFor(() => {
      expect(mockAddCar).toHaveBeenCalledWith({
        make: 'Ford',
        model: 'Focus',
        year: new Date().getFullYear(),
        price: 18000,
        color: undefined,
        mileage: undefined,
        status: 'AVAILABLE',
        description: undefined,
      });
    });
  });

  it('displays submission error message when addCar throws an error', async () => {
    const user = userEvent.setup();
    mockAddCar.mockRejectedValueOnce(new Error('Network error occurred'));

    render(<AddCarForm />);

    await user.type(screen.getByLabelText(/make/i), 'Mazda');
    await user.type(screen.getByLabelText(/model/i), 'CX-5');
    await user.type(screen.getByLabelText(/price/i), '28000');

    await user.click(screen.getByRole('button', { name: /add car/i }));

    expect(await screen.findByText('Network error occurred')).toBeInTheDocument();
  });

  it('displays fallback error message when addCar throws non-error object', async () => {
    const user = userEvent.setup();
    mockAddCar.mockRejectedValueOnce({});

    render(<AddCarForm />);

    await user.type(screen.getByLabelText(/make/i), 'Mazda');
    await user.type(screen.getByLabelText(/model/i), 'CX-5');
    await user.type(screen.getByLabelText(/price/i), '28000');

    await user.click(screen.getByRole('button', { name: /add car/i }));

    expect(
      await screen.findByText('Failed to add car. Please try again.')
    ).toBeInTheDocument();
  });

  it('displays addCarError from useCars hook when present', () => {
    mockUseCars.mockReturnValue({
      ...defaultHookReturn,
      addCarError: new Error('Hook error occurred'),
    } as any);

    render(<AddCarForm />);

    expect(screen.getByText('Hook error occurred')).toBeInTheDocument();
  });

  it('disables form fields and buttons when addingCar is true', () => {
    mockUseCars.mockReturnValue({
      ...defaultHookReturn,
      addingCar: true,
    } as any);

    render(<AddCarForm />);

    expect(screen.getByLabelText(/make/i)).toBeDisabled();
    expect(screen.getByLabelText(/model/i)).toBeDisabled();
    expect(screen.getByLabelText(/year/i)).toBeDisabled();
    expect(screen.getByLabelText(/price/i)).toBeDisabled();
    expect(screen.getByLabelText(/color/i)).toBeDisabled();
    expect(screen.getByLabelText(/mileage/i)).toBeDisabled();
    expect(screen.getByLabelText(/description/i)).toBeDisabled();
    expect(screen.getByRole('button', { name: /adding car\.\.\./i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /reset/i })).toBeDisabled();
  });

  it('resets form fields and calls onCancel when cancel/reset button is clicked', async () => {
    const user = userEvent.setup();
    const onCancel = vi.fn();

    render(<AddCarForm onCancel={onCancel} />);

    const makeInput = screen.getByLabelText(/make/i);
    await user.type(makeInput, 'Subaru');
    expect(makeInput).toHaveValue('Subaru');

    await user.click(screen.getByRole('button', { name: /cancel/i }));

    expect(makeInput).toHaveValue('');
    expect(onCancel).toHaveBeenCalledTimes(1);
  });
});
